function build(M) {
  const t = m => M.T(m, {rx: 40});
  const glass = M.merge([M.cyl(1.6, 0.12, 48, 0), M.T(M.torus(1.6, 0.025, 48, 10), {pos: [0, 0.06, 0]})]);
  const track = [];
  let p = null;
  for (let i = 0; i <= 300; i++) {
    const a = i * 0.16, r = 0.45 + 1.05 * i / 300;
    const q = [r * Math.cos(a), 0.125, r * Math.sin(a)];
    if (p) track.push(M.pipe(p, q, 0.008, 6));
    p = q;
  }
  const base = [M.cyl(1.72, 0.1, 48, -0.1), M.cyl(1.2, 0.18, 40, -0.28), M.cyl(0.8, 0.12, 32, -0.4)];
  for (let i = 0; i < 12; i++) {
    const a = i * Math.PI / 6;
    base.push(M.T(M.cyl(0.04, 0.02, 12, 0), {pos: [1.64 * Math.cos(a), 0, 1.64 * Math.sin(a)]}));
  }
  const hub = M.merge([M.cyl(0.2, 0.08, 28, 0.12), M.cyl(0.08, 0.05, 20, 0.2), M.T(M.torus(0.2, 0.02, 28, 8), {pos: [0, 0.2, 0]})]);
  return [
    {material: 'glass', look: 'glass', mesh: t(glass)},
    {material: 'blue', look: 'glow', mesh: t(M.merge(track))},
    {material: 'dark_steel', look: 'solid', mesh: t(M.merge(base))},
    {material: 'steel', look: 'solid', mesh: t(hub)}
  ];
}

function build(M) {
  const t = m => M.T(m, {rx: 40});
  const plate = M.lathe([[0.28, 0], [1.6, 0], [1.6, 0.12], [0.28, 0.12], [0.28, 0]], 48);
  const bumps = [];
  for (let ring = 0; ring < 7; ring++) {
    const r = 0.5 + ring * 0.17;
    const n = 16 + ring * 5;
    for (let i = 0; i < n; i++) {
      if ((i + ring) % 4 === 3) continue;
      const a = i * 2 * Math.PI / n;
      bumps.push(M.T(M.box(0.09 + 0.05 * (i % 3), 0.04, 0.035, 0), {pos: [r * Math.cos(a), 0.12, r * Math.sin(a)], ry: -a * 180 / Math.PI + 90}));
    }
  }
  const rims = [M.T(M.torus(1.6, 0.03, 48, 10), {pos: [0, 0.06, 0]}), M.T(M.torus(0.28, 0.03, 32, 10), {pos: [0, 0.12, 0]})];
  const back = [M.lathe([[0.32, -0.08], [1.5, -0.08], [1.5, 0], [0.32, 0], [0.32, -0.08]], 48)];
  for (let i = 0; i < 8; i++) {
    const a = i * Math.PI / 4;
    back.push(M.T(M.cyl(0.035, 0.025, 12, 0), {pos: [1.5 * Math.cos(a), 0.12, 1.5 * Math.sin(a)]}));
  }
  return [
    {material: 'steel', look: 'solid', mesh: t(M.merge([plate].concat(bumps)))},
    {material: 'copper', look: 'solid', mesh: t(M.merge(rims))},
    {material: 'dark_steel', look: 'solid', mesh: t(M.merge(back))}
  ];
}

