function build(M) {
  const lengths = [0.5, 0.25, 0.7, 0.35, 0.9, 0.3, 0.55, 0.4, 0.75, 0.25, 0.6];
  const gaps = [0.2, 0.32, 0.18, 0.4, 0.22, 0.3, 0.2, 0.36];
  const lands = [], floors = [];
  const rows = [-0.55, 0, 0.55];
  rows.forEach((z, row) => {
    floors.push(M.T(M.box(3.9, 0.02, 0.28, -0.25), {pos: [0, 0, z]}));
    let x = -1.95, i = row * 3;
    while (x < 1.8) {
      const len = Math.min(lengths[i % lengths.length], 1.95 - x);
      lands.push(M.T(M.box(len, 0.13, 0.28, -0.25), {pos: [x + len / 2, 0, z]}));
      x += len + gaps[i % gaps.length];
      i++;
    }
  });
  const strips = [];
  for (const z of [-0.84, -0.275, 0.275, 0.84]) strips.push(M.T(M.box(3.9, 0.13, 0.27, -0.25), {pos: [0, 0, z]}));
  const base = M.merge([M.box(4, 0.3, 2, -0.55), M.T(M.box(4.04, 0.04, 2.04, 0), {pos: [0, -0.57, 0]})]);
  const clear = M.box(4, 0.45, 2, -0.12);
  return [
    {material: 'dark_steel', look: 'solid', mesh: base},
    {material: 'blue', look: 'solid', mesh: M.merge(floors)},
    {material: 'steel', look: 'solid', mesh: M.merge(lands.concat(strips))},
    {material: 'glass', look: 'glass', mesh: clear}
  ];
}

