  const window = M.box(0.8, 0.05, 0.8, -0.09);
  const cells = [];
  for (let i = 0; i < 4; i++) for (let j = 0; j < 4; j++) {
    cells.push(M.T(M.box(0.15, 0.015, 0.15, 0), {pos: [-0.27 + i * 0.18, -0.09, -0.27 + j * 0.18]}));
  }
  const pins = [];
  for (let i = 0; i < 8; i++) {
    const p = -0.49 + i * 0.14;
    pins.push(M.box(0.07, 0.03, 0.26, -0.27, p));
    pins.push(M.T(M.box(0.07, 0.03, 0.26, -0.27, p), {pos: [0, 0, 0]}));
  }
  const shifted = pins.map((m, i) => M.T(m, {pos: [0, 0, i % 2 ? 0.66 : -0.66]}));
  const traces = [];
  for (let i = 0; i < 6; i++) traces.push(M.T(M.box(0.04, 0.01, 0.5, -0.25), {pos: [-0.5 + i * 0.2, 0, 0.74]}));
  const screws = [];
  for (const x of [-0.85, 0.85]) for (const z of [-0.85, 0.85]) screws.push(M.T(M.cyl(0.06, 0.03, 14, -0.25), {pos: [x, 0, z]}));
  const led = M.T(M.cyl(0.05, 0.04, 14, -0.25), {pos: [0.8, 0, 0.3]});
  return [
    {material: 'green', look: 'solid', mesh: t(board)},
    {material: 'dark_steel', look: 'solid', mesh: t(M.merge(chip))},
    {material: 'gold', look: 'solid', mesh: t(M.merge(shifted.concat(traces)))},
    {material: 'solar', look: 'screen', mesh: t(M.merge(cells))},
    {material: 'glass', look: 'glass', mesh: t(window)},
    {material: 'steel', look: 'solid', mesh: t(M.merge(screws))},
    {material: 'green', look: 'led', mesh: t(led)}
